# bash completion for swath; generated by swath completion bash

_swath_kind() {
    case $1 in
    --color) echo 'enum auto always never';;
    --output|-o) echo 'file';;
    --format) echo 'enum auto table tsv jsonl';;
    --include) echo 'value';;
    --exclude) echo 'value';;
    --min-size) echo 'value';;
    --max-size) echo 'value';;
    --modified-since) echo 'value';;
    --modified-until) echo 'value';;
    --storage-class) echo 'value';;
    --workers|-j) echo 'value';;
    --encoders) echo 'value';;
    --row-budget) echo 'value';;
    --spill-budget) echo 'value';;
    --part-size) echo 'value';;
    --part-interval) echo 'value';;
    --part-rotation-max-rows) echo 'value';;
    --seed-from) echo 'file';;
    --max-duration) echo 'value';;
    --stall-timeout) echo 'value';;
    --report) echo 'file';;
    --progress-interval) echo 'value';;
    --endpoint-url) echo 'value';;
    --request-timeout) echo 'value';;
    --request-rate) echo 'value';;
    --metadata) echo 'enum names stat statx';;
    --azure-sas-token) echo 'value';;
    --gcs-credentials-file) echo 'file';;
    --gcs-billing-project) echo 'value';;
    --s3-region) echo 'value';;
    --s3-profile) echo 'value';;
    --s3-bearer-token-command) echo 'value';;
    --s3-bearer-token-refresh-interval) echo 'value';;
    --depth|-d) echo 'value';;
    --max-prefixes) echo 'value';;
    --max-inodes) echo 'value';;
    --spill-reserve) echo 'value';;
    --structure) echo 'enum auto on off';;
    --max-keys) echo 'value';;
    --page-size) echo 'value';;
    esac
}

_swath_flags() {
    case $1 in
    '') echo '--verbose -v --quiet -q --color --help -h --version -V';;
    'list') echo '--output -o --format --overwrite --include --exclude --min-size --max-size --modified-since --modified-until --storage-class --workers -j --encoders --row-budget --spill-budget --part-size --part-interval --part-rotation-max-rows --seed-from --max-duration --stall-timeout --report --verbose -v --quiet -q --progress --no-progress --progress-interval --stats --no-stats --color --anonymous --endpoint-url --request-timeout --all-versions --request-rate --no-adaptive-limit --metadata --no-dirs --no-link-target --one-file-system --azure-sas-token --azure-assume-flat --gcs-credentials-file --gcs-billing-project --s3-region --s3-profile --s3-requester-pays --s3-path-style --no-s3-path-style --s3-bearer-token-command --s3-bearer-token-refresh-interval --s3-fips --s3-dualstack --s3-fetch-owner --help -h';;
    'du') echo '--depth -d --allocated --count-links-once --max-prefixes --max-inodes --format --include --exclude --min-size --max-size --modified-since --modified-until --storage-class --workers -j --seed-from --max-duration --stall-timeout --report --verbose -v --quiet -q --progress --no-progress --progress-interval --stats --no-stats --color --anonymous --endpoint-url --request-timeout --all-versions --request-rate --no-adaptive-limit --metadata --no-dirs --no-link-target --one-file-system --azure-sas-token --azure-assume-flat --gcs-credentials-file --gcs-billing-project --s3-region --s3-profile --s3-requester-pays --s3-path-style --no-s3-path-style --s3-bearer-token-command --s3-bearer-token-refresh-interval --s3-fips --s3-dualstack --s3-fetch-owner --help -h';;
    'diag list') echo '--no-spill-compress --spill-plain --no-journal --no-spill --spill-reserve --adaptive-limit-slow-start --no-seed --structure --slow-split --floors --sequential --max-keys --page-size --help -h';;
    'diag count') echo '--include --exclude --min-size --max-size --modified-since --modified-until --storage-class --workers -j --seed-from --max-duration --stall-timeout --report --verbose -v --quiet -q --progress --no-progress --progress-interval --stats --no-stats --color --anonymous --endpoint-url --request-timeout --all-versions --request-rate --no-adaptive-limit --adaptive-limit-slow-start --no-seed --structure --slow-split --floors --sequential --max-keys --page-size --metadata --no-dirs --no-link-target --one-file-system --azure-sas-token --azure-assume-flat --gcs-credentials-file --gcs-billing-project --s3-region --s3-profile --s3-requester-pays --s3-path-style --no-s3-path-style --s3-bearer-token-command --s3-bearer-token-refresh-interval --s3-fips --s3-dualstack --s3-fetch-owner --help -h';;
    'resume') echo '--workers -j --encoders --row-budget --spill-budget --part-interval --seed-from --max-duration --stall-timeout --report --verbose -v --quiet -q --progress --no-progress --progress-interval --stats --no-stats --color --no-spill-compress --spill-plain --spill-reserve --anonymous --request-timeout --request-rate --no-adaptive-limit --adaptive-limit-slow-start --azure-sas-token --gcs-credentials-file --s3-profile --s3-bearer-token-command --s3-bearer-token-refresh-interval --help -h';;
    'show') echo '--journal --help -h';;
    esac
}

_swath() {
    local cur prev cmd sub i w flag kind
    cur=${COMP_WORDS[COMP_CWORD]}
    prev=
    ((COMP_CWORD > 0)) && prev=${COMP_WORDS[COMP_CWORD-1]}
    COMPREPLY=()

    # --flag=value arrives as three words: --flag, = and the value.
    if [[ $cur == = ]]; then
        flag=$prev cur=
    elif [[ $prev == = ]]; then
        flag=${COMP_WORDS[COMP_CWORD-2]}
    elif [[ $prev == -* ]]; then
        flag=$prev
    fi

    for ((i = 1; i < COMP_CWORD; i++)); do
        w=${COMP_WORDS[i]}
        case $w in
        --color)
            ((i++))
            [[ ${COMP_WORDS[i]} == = ]] && ((i++))
            continue;;
        -*) continue;;
        esac
        if [[ -z $cmd ]]; then
            cmd=$w
            [[ $cmd == diag ]] || break
        else
            sub=$w
            break
        fi
    done
    [[ $cmd == ls ]] && cmd=list
    [[ $cmd == diag && -n $sub ]] && cmd="diag $sub"

    if [[ -n $flag ]]; then
        kind=$(_swath_kind "$flag")
        case ${kind%% *} in
        enum) COMPREPLY=($(compgen -W "${kind#enum }" -- "$cur"));;
        file) COMPREPLY=($(compgen -f -- "$cur")); compopt -o filenames 2>/dev/null;;
        dir) COMPREPLY=($(compgen -d -- "$cur")); compopt -o filenames 2>/dev/null;;
        esac
        [[ -n $kind ]] && return
    fi

    if [[ $cur == -* ]]; then
        COMPREPLY=($(compgen -W "$(_swath_flags "$cmd")" -- "$cur"))
        return
    fi

    case $cmd in
    '') COMPREPLY=($(compgen -W 'list ls du resume show diag completion help version' -- "$cur"));;
    help) COMPREPLY=($(compgen -W 'list ls du resume show diag completion help version' -- "$cur"));;
    diag) COMPREPLY=($(compgen -W 'list count' -- "$cur"));;
    completion) COMPREPLY=($(compgen -W 'bash zsh fish' -- "$cur"));;
    'list'|'du'|'diag list'|'diag count')
        COMPREPLY=($(compgen -W 'az:// gs:// s3://' -- "$cur") $(compgen -d -- "$cur"))
        compopt -o filenames 2>/dev/null
        [[ ${#COMPREPLY[@]} -eq 1 && ${COMPREPLY[0]} == *:// ]] && compopt -o nospace 2>/dev/null;;
    'resume'|'show') COMPREPLY=($(compgen -d -- "$cur")); compopt -o filenames 2>/dev/null;;
    esac
}

complete -F _swath swath
